import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.CcrBcQWS.js";const g=JSON.parse('{"title":"High Level Command — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/high-level.md","filePath":"software/sdk/cpp/high-level.md","lastUpdated":1787021357000}'),o={name:"software/sdk/cpp/high-level.md"};function d(n,t,l,r,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="high-level-command-—-c-example" tabindex="-1">High Level Command — C++ Example <a class="header-anchor" href="#high-level-command-—-c-example" aria-label="Permalink to &quot;High Level Command — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_high_level.cpp</code></p><p>Publishes <code>HighLevelCommand</code> messages at <strong>50 Hz</strong> over DDS.<br> Gait selection is done from the terminal; velocity setpoints come from a joystick.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Three concurrent actors run together:</p><table tabindex="0"><thead><tr><th>Actor</th><th>Rate</th><th>Role</th></tr></thead><tbody><tr><td><strong>Control loop thread</strong></td><td>50 Hz</td><td>Publishes <code>HighLevelCommand</code> with the current gait + velocity</td></tr><tr><td><strong>Joystick loop thread</strong></td><td>100 Hz</td><td>Polls the joystick and updates atomic velocity globals</td></tr><tr><td><strong>Main thread</strong> (terminal)</td><td>blocking</td><td>Reads gait names/IDs from stdin and updates the target gait</td></tr></tbody></table><p>At startup the control loop also publishes <code>switchControlMode = true</code> once, which enables <strong>EXT_JOY mode</strong> on the robot stack — without this the <code>HighLevelCommand</code> topic is ignored.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>A Linux joystick device at <code>/dev/input/js*</code> (the joystick is <strong>required</strong> to start the program).</li><li>Robot stack running (simulation or hardware).</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_high_level</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e.g.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>The joystick auto-detection follows the same logic as the Sport Client (Joystick) example.</p><h2 id="terminal-commands" tabindex="-1">Terminal commands <a class="header-anchor" href="#terminal-commands" aria-label="Permalink to &quot;Terminal commands&quot;">​</a></h2><p>At the <code>&gt;</code> prompt type either a <strong>gait name</strong> or a <strong>numeric gait ID</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list              # print the example&#39;s built-in list</span></span>
<span class="line"><span>standing          # switch to STANDING by name</span></span>
<span class="line"><span>3                 # switch to TROTTING by ID</span></span>
<span class="line"><span>waving            # switch to WAVING by name</span></span></code></pre></div><h2 id="supported-gaits" tabindex="-1">Supported gaits <a class="header-anchor" href="#supported-gaits" aria-label="Permalink to &quot;Supported gaits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>ID</th><th>Description</th></tr></thead><tbody><tr><td><code>sitting</code></td><td>0</td><td>Robot sits on the ground</td></tr><tr><td><code>standing</code></td><td>1</td><td>Neutral standing posture (default at startup)</td></tr><tr><td><code>trotting</code></td><td>3</td><td>MPC trot gait</td></tr><tr><td><code>trot_stairs</code></td><td>4</td><td>Stair-adaptive trot</td></tr><tr><td><code>waving</code></td><td>5</td><td>Slow walk gait</td></tr><tr><td><code>docking</code></td><td>10</td><td>Auto-docking sequence</td></tr></tbody></table><blockquote><p>The example&#39;s built-in list also prints internal gaits that are not supported. Use only the gaits in the table above.</p></blockquote><h2 id="joystick-velocity-controls" tabindex="-1">Joystick velocity controls <a class="header-anchor" href="#joystick-velocity-controls" aria-label="Permalink to &quot;Joystick velocity controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Axis</th><th>Maps to</th><th>Max value</th></tr></thead><tbody><tr><td>Left stick Y (forward)</td><td><code>vel_x</code></td><td>±1.2 m/s</td></tr><tr><td>Left stick X (lateral)</td><td><code>vel_y</code></td><td>±0.5 m/s</td></tr><tr><td>Right stick X (yaw)</td><td><code>omega_z</code></td><td>±60 deg/s</td></tr></tbody></table><p>A deadzone of <strong>0.12</strong> is applied before scaling.</p><blockquote><p><strong>Note on <code>omega_z</code> units</strong>: <code>HighLevelCommand.omega_z</code> is sent in <strong>degrees per second</strong>.<br> The on-robot QuadWalk multiplies by D2R internally, so the SDK side sends raw deg/s values (e.g. 60 deg/s ≈ 1.05 rad/s of yaw).</p></blockquote><h2 id="dds-topics-used" tabindex="-1">DDS topics used <a class="header-anchor" href="#dds-topics-used" aria-label="Permalink to &quot;DDS topics used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Topic</th><th>Message type</th></tr></thead><tbody><tr><td>Publish</td><td><code>rt/rbq/cmd/high_level</code></td><td><code>rbq_msgs::msg::dds_::HighLevelCommand_</code></td></tr><tr><td>Publish</td><td><code>rt/rbq/cmd/switch_control_mode</code></td><td><code>std_msgs::msg::dds_::Bool_</code></td></tr></tbody></table><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong><code>gait_transition</code> flag</strong>: Set to <code>true</code> only on the single tick immediately following a gait change, using <code>std::atomic&lt;bool&gt;::exchange()</code>. This ensures the QuadWalk <code>gaitTimer</code> is triggered exactly once rather than continuously.</li><li><strong><code>switchControlMode</code></strong>: Published once at startup (after a 200 ms delay to let DDS subscribers connect). If not published, the robot ignores <code>HighLevelCommand</code> and stays in joystick mode.</li><li><strong>Timing</strong>: The control loop uses <code>clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, ...)</code> for precise 20 ms scheduling. If the loop runs late, it resets <code>timeNext</code> to the current time rather than chasing a drifting target.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/sdk/cpp/sport-client.html">Sport Client</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/sport-client-joy.html">Sport Client (Joystick)</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/low-level.html">Low Level (RL Policy)</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a></li></ul>`,32)])])}const u=e(o,[["render",d]]);export{g as __pageData,u as default};
